async def _apply_atom_policy(self, results, query: str = ""):
        """Resolve atom-backed recall content from current lifecycle state.

        Args:
            results: Document candidates, including cached or recent results.

        Returns:
            Candidates containing only live facts; fully expired parents are omitted.
        """
        if not results:
            return results
        if not self.atom_enabled or self.atom_store is None:
            return self._clean_recall_candidates(results, query)
        ids = list(dict.fromkeys(result.doc_id for result in results))
        grouped = {}
        for start in range(0, len(ids), 500):
            batch = ids[start : start + 500]
            cursor = await self.db_connection.execute(
                f"SELECT id, parent_memory_id, content, status, expires_at FROM memory_atoms "
                f"WHERE parent_memory_id IN ({','.join('?' for _ in batch)}) ORDER BY id",
                batch,
            )
            for row in await cursor.fetchall():
                grouped.setdefault(int(row[1]), []).append(row)
        now = time.time()
        filtered = []
        for result in results:
            atoms = grouped.get(result.doc_id)
            if atoms is None and not result.metadata.get("atom_types"):
                filtered.append(result)
                continue
            active = [
                row for row in (atoms or []) if row[3] == "active" and row[4] > now
            ]
            if not active:
                continue
            filtered.append(
                replace(
                    result,
                    content="\n".join(dict.fromkeys(str(row[2]) for row in active)),
                    metadata={
                        **result.metadata,
                        "retrieved_atom_ids": [int(row[0]) for row in active],
                        "recall_atom_policy_applied": True,
                    },
                )
            )
        return self._clean_recall_candidates(filtered, query)

def _clean_recall_candidates(self, results, query: str):
        cleaned = []
        for result in results:
            metadata = dict(result.metadata)
            content, caveats, statuses = split_evidence(result.content)
            if not content and not caveats:
                continue
            metadata["recall_evidence_filtered"] = True
            metadata["recall_caveats"] = list(dict.fromkeys(
                [*metadata.get("recall_caveats", []), *caveats]
            ))
            metadata["recall_status_notes"] = list(dict.fromkeys(
                [*metadata.get("recall_status_notes", []), *statuses]
            ))
            if metadata.get("recall_atom_policy_applied"):
                metadata["key_facts"] = content.splitlines()
            else:
                metadata["key_facts"] = [
                    fact for value in metadata.get("key_facts", [])
                    if (fact := split_evidence(str(value))[0])
                ]
            metadata["contextual_mentions"] = contextual_mentions(
                query, str(metadata.get("persona_summary", "")) + "\n" + result.content
            )
            cleaned.append(replace(result, content=content, metadata=metadata))
        return cleaned

async def _rerank_final_results(self, query, results, k):
        if not results or not self.config.get("rerank_enabled", False):
            return results[:k]
        resolver = getattr(self, "rerank_provider_resolver", None)
        if not callable(resolver):
            return results[:k]
        try:
            provider = resolver()
            if provider is None:
                return results[:k]
            limit = max(k, min(100, int(self.config.get("rerank_candidates", 20))))
            # Keep literal entity/topic matches even when graph scores are weak.
            candidates = [r for r in results if r.metadata.get("contextual_mentions")]
            ids = {r.doc_id for r in candidates}
            candidates.extend(r for r in results if r.doc_id not in ids)
            candidates = candidates[:limit]
            documents = [json.dumps({
                "facts": r.content,
                "participants": r.metadata.get("participants", []),
                "historical_mentions": r.metadata.get("contextual_mentions", []),
            }, ensure_ascii=False) for r in candidates]
            ranked = await asyncio.wait_for(
                provider.rerank(query=query, documents=documents),
                timeout=float(self.config.get("retrieval_timeout_seconds", 10.0)),
            )
            scores = {
                item.index: float(item.relevance_score) for item in ranked
                if 0 <= item.index < len(candidates) and math.isfinite(float(item.relevance_score))
            }
            if not scores:
                return results[:k]
            reranked = [replace(
                result,
                final_score=scores.get(index, 0.0),
                score_breakdown={**(result.score_breakdown or {}),
                    "pre_final_rerank": result.final_score,
                    "final_rerank": scores.get(index, 0.0)},
            ) for index, result in enumerate(candidates)]
            reranked.sort(key=lambda r: r.final_score, reverse=True)
            logger.info("[memory_recall] 最终重排序完成: candidates=%s, selected_ids=%s",
                        len(candidates), [r.doc_id for r in reranked[:k]])
            return reranked[:k]
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logger.warning("[memory_recall] 最终重排序失败，保留原检索结果: %s", exc)
            return results[:k]

