async def add_document(self, content, metadata=None):
    for attempt in range(3):
        try:
            return await _memory_fix_original_add_document(self, content, metadata)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            if attempt == 2 or not is_embedding_transport_error(exc):
                raise
            logger.warning("[memory_recall_fix] Embedding transport failed; retry %s/2 (%s)", attempt + 1, type(exc).__name__)
            await asyncio.sleep(0.5 * (2 ** attempt))
